import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.shared.aashell.genericaashell import GenericAashell


class Log(GenericAashell):
    """Log command class."""

    def __init__(self, connection, filename="logfile.zip", options=None, prompt=None, newline_chars=None, runner=None):
        """
        Collect logs from hub.

        :param filename: name of the log file, default: logfile.zip
        :param connection: moler connection to device, terminal when command is executed
        :param prompt: Prompt of the starting shell
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Log, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.filename = filename
        self.options = options
        self.current_ret["add_files"] = []
        self.current_ret["copy_files"] = []
        self.current_ret["error_files"] = []
        self.current_ret["RESULT"] = []
        self.current_ret["SUCCESS"] = False

        self._re_parse_error = re.compile(r"(?P<ERROR>Cannot execute the command.*|is not a valid command.*|Invalid option.*)", re.IGNORECASE)

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        cmd = "log"
        if self.options:
            cmd = f"{cmd} {self.options}"
        cmd = f"{cmd} {self.filename}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Execute all parsing methods.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_line(line)
                self._parse_line_success(line)
                self._parse_add_file_to_zip(line)
                self._parse_copy_file_to_zip(line)
                self._parse_error_files(line)
            except ParsingDone:
                pass
        return super(Log, self).on_new_line(line, is_full_line)

    def _parse_line(self, line):
        self.current_ret["RESULT"].append(line)

    # AaSysComUserDeregister succeed
    _re_success_v1 = r"AaSysComUserDeregister\s+succeed"
    # Log collection finished!.
    _re_success_v2 = r"Log collection finished!"
    _re_success = re.compile(f"{_re_success_v1}|{_re_success_v2}")

    def _parse_line_success(self, line):
        if self._regex_helper.search_compiled(Log._re_success, line):
            self.current_ret["SUCCESS"] = True
            raise ParsingDone

    # Add file '/ram/1011_runtime_HWAPI_DBG_GnssS.log' to zip 'snapshot.zip'
    _re_add_file_path = re.compile(r"^Add\s+file\s+\'(?P<ADD_FILE>\S+)\'")

    def _parse_add_file_to_zip(self, line):
        """
        Parse add files from the line of command output.

        :param line: Line of output of command.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Log._re_add_file_path, line):
            self.current_ret["add_files"].append(self._regex_helper.group("ADD_FILE"))
            raise ParsingDone

    # Copy file '/ram' to '/ram/1011_CELLC_static_counters.txt'
    _re_copy_file_path = re.compile(r"^Copy\s+file\s+\'(?P<COPY_FILE_FROM>\S+)\'\s+to\s+\'(?P<COPY_FILE_TO>\S+)\'")

    def _parse_copy_file_to_zip(self, line):
        """
        Parse copy file from the line of command output.

        :param line: Line of output of command.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Log._re_copy_file_path, line):
            self.current_ret["copy_files"].append(
                {
                    "FROM": self._regex_helper.group("COPY_FILE_FROM"),
                    "TO": self._regex_helper.group("COPY_FILE_TO"),
                }
            )
            raise ParsingDone

    # Error in opening /ram/1011_CELLC_static_counters.txt for reading
    _re_error_file_path = re.compile(r"^Error\s+in\s+opening\s+(?P<ERROR_FILE>\S+)")

    def _parse_error_files(self, line):
        """
        Parse files with error from the line of command output.

        :param line: Line of output of command.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Log._re_error_file_path, line):
            if self._regex_helper.group("ERROR_FILE") not in self.current_ret["error_files"]:
                self.current_ret["error_files"].append(self._regex_helper.group("ERROR_FILE"))
            raise ParsingDone


